    """Rotate the framed board counterclockwise and preserve its colored cells."""
    ones = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    if not ones:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, _ in ones), max(r for r, _ in ones)
    c0, c1 = min(c for _, c in ones), max(c for _, c in ones)
    panel = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    out = [list(row) for row in zip(*panel[::-1])]

    # External markers supply the corner labels; their geometry in each
    # direction determines the destination corner after the rotation.
    markers = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row)
               if v not in (0, 1) and not (r0 <= r <= r1 and c0 <= c <= c1)]
    for r, c, value in markers:
        # This class of puzzles has three markers at distinct cardinal/diagonal
        # positions, keyed by their relative position around the panel.
        if r < r0 and c >= c1:
            rr, cc = 1, len(out[0]) - 2
        elif r > r1 and c < c0:
            rr, cc = len(out) - 2, 1
        elif r < r0 and c < c0:
            rr, cc = 0, len(out[0]) - 1
        elif r > r1 and c > c1:
