        elif r < r0:
            rr, cc = 0, len(out[0]) - 1
        elif r > r1:
            rr, cc = len(out) - 1, 0
        elif c < c0:
            rr, cc = 0, 0
        else:
            rr, cc = len(out) - 1, len(out[0]) - 1
        if 0 <= rr < len(out) and 0 <= cc < len(out[0]):
            out[rr][cc] = value
    return out

